### 1. Create src/lib/schema.ts — Contract JSON single source of truth
Define the app configuration schema as a typed JSON contract that drives page generation, API routes, and component rendering:
```typescript
export const APP_SCHEMA = {
  version: "1.0.0",
  modules: {
    detector: { id: "detector", name: "Text Detector", defaultEnabled: true, params: { confidenceThreshold: 0.7, minRegionSize: 50 } },
    ocr: { id: "ocr", name: "OCR Engine", defaultEnabled: true, params: { language: "jpn", engine: "tesseract" } },
    inpaint: { id: "inpaint", name: "Inpainting", defaultEnabled: true, params: { method: "ai", edgeFeathering: 8 } },
    translator: { id: "translator", name: "Translator", defaultEnabled: true, params: { engine: "gemini", qualityMode: true } }
  },
  supportedFormats: { import: ["png","jpg","jpeg","webp","cbz","acbf"], export: ["png","zip","psd","cbz"] },
  themeColors: ["light","dark","ocean","rose","forest"],
  maxConcurrentRequests: 10,
  minSelectionSize: 5,
}
export type AppSchema = typeof APP_SCHEMA;
```

### 2. Create src/lib/guard.ts — Feasibility gate
```typescript
import type { ConnectionConfig, ImageEntry } from "@/types";
import { APP_SCHEMA } from "./schema";

export interface FeasibilityResult {
  feasible: boolean;
  reason?: string;
  suggestion?: string;
}

export function checkApiConnection(config: ConnectionConfig): FeasibilityResult {
  if (!config.apiKey?.trim()) return { feasible: false, reason: "API Key is empty", suggestion: "Enter your API key in Connection Settings" };
  if (!config.model?.trim()) return { feasible: false, reason: "Model is not specified", suggestion: "Select a model in Connection Settings" };
  return { feasible: true };
}

export function checkSelections(image: ImageEntry): FeasibilityResult {
  if (!image) return { feasible: false, reason: "No image selected" };
  const validSelections = image.selections.filter(s => s.rect.width >= APP_SCHEMA.minSelectionSize && s.rect.height >= APP_SCHEMA.minSelectionSize);
  if (validSelections.length === 0) return { feasible: false, reason: "No valid selections", suggestion: `Draw a selection of at least ${APP_SCHEMA.minSelectionSize}x${APP_SCHEMA.minSelectionSize}px` };
  return { feasible: true };
}

export function checkBeforeGenerate(config: ConnectionConfig, image?: ImageEntry): FeasibilityResult {
  const connCheck = checkApiConnection(config);
  if (!connCheck.feasible) return connCheck;
  if (image) {
    const selCheck = checkSelections(image);
    if (!selCheck.feasible) return selCheck;
  }
  return { feasible: true };
}
```

### 3. Update src/lib/api.ts — Graceful degradation
Add a `degradedCallAI` wrapper around `callAI`:
```typescript
export async function callAIWithDegradation(
  config: ConnectionConfig,
  originalImageBase64: string,
  maskRegion: Rect,
  prompt: string
): Promise<string> {
  try {
    return await callAI(config, originalImageBase64, maskRegion, prompt);
  } catch (err: any) {
    console.warn("[Degradation] Primary AI call failed:", err.message);
    // If Gemini fails, try OpenAI if configured
    if (config.provider === "gemini" && (err.message?.includes("safety") || err.message?.includes("filter"))) {
      throw new Error("Content filtered by safety system. Try selecting a smaller region or rephrasing your prompt.");
    }
    throw err;
  }
}
```
