  const glossaryStr = Object.entries(translationContext.termGlossary).map(([k,v]) => `${k}=${v}`).join(", ");

  const contextualPrompt = `Previous translations for context:\n${contextStr}\n\nGlossary: ${glossaryStr}\n\nTranslate: ${text}`;

  const result = await translateText(contextualPrompt, sourceLang, targetLang, config);
  addToContext(text, result);
  return result;
}
```

### 5. Create src/lib/typesetting.ts — Basic typesetting engine
```typescript
export interface TypesettingOptions {
  fontFamily: string;
  fontSize: number;
  maxWidth: number;
  maxHeight: number;
  lineHeight: number;
  alignment: 'left' | 'center' | 'right';
  direction: 'horizontal' | 'vertical';
  color: string;
  bold: boolean;
  italic: boolean;
}

export function computeTextLayout(text: string, options: TypesettingOptions): Array<{ text: string; x: number; y: number; width: number }> {
  // Simple line-breaking: split by characters (for CJK) or words (for Latin)
  const isCJK = /[\u4e00-\u9fff\u3040-\u309f\u30a0-\u30ff]/.test(text);
  const chars = isCJK ? text.split('') : text.split(/\s+/);

  const lines: string[] = [];
  let currentLine = '';
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d')!;
  ctx.font = `${options.bold ? 'bold ' : ''}${options.italic ? 'italic ' : ''}${options.fontSize}px ${options.fontFamily}`;

  for (const char of chars) {
    const testLine = currentLine + (isCJK ? char : ' ' + char);
    const metrics = ctx.measureText(testLine);
    if (metrics.width > options.maxWidth && currentLine) {
      lines.push(currentLine.trim());
      currentLine = isCJK ? char : char;
    } else {
      currentLine = testLine;
    }
  }
  if (currentLine.trim()) lines.push(currentLine.trim());

  const results: Array<{ text: string; x: number; y: number; width: number }> = [];
  const totalHeight = lines.length * options.lineHeight * options.fontSize;
  const startY = options.alignment === 'center' ? (options.maxHeight - totalHeight) / 2 : 0;

  for (let i = 0; i < lines.length; i++) {
    const metrics = ctx.measureText(lines[i]);
    const x = options.alignment === 'center' ? (options.maxWidth - metrics.width) / 2 : options.alignment === 'right' ? options.maxWidth - metrics.width : 0;
    results.push({ text: lines[i], x, y: startY + i * options.lineHeight * options.fontSize, width: metrics.width });
  }

  return results;
}
```

### 6. Create src/lib/acbf.ts — ACBF format support
```typescript
import type { ImageEntry } from "@/types";

export interface ACBFMetadata {
  title: string;
  authors: string[];
  language: string;
  pages: Array<{ image: string; textRegions: Array<{ x: number; y: number; width: number; height: number; text: string }> }>;
}

export function parseACBF(xmlString: string): ACBFMetadata {
  const parser = new DOMParser();
  const doc = parser.parseFromString(xmlString, "text/xml");

  const metadata = doc.querySelector("metadata");
  const title = metadata?.querySelector("title")?.textContent || "Untitled";
  const authors = Array.from(metadata?.querySelectorAll("author") || []).map(a => a.textContent || "");
  const lang = metadata?.querySelector("language")?.textContent || "en";

  const pages: ACBFMetadata["pages"] = [];
  const body = doc.querySelector("body");
  body?.querySelectorAll("page").forEach(page => {
    const image = page.getAttribute("image") || "";
    const regions: ACBFMetadata["pages"][0]["textRegions"] = [];
    page.querySelectorAll("text-region").forEach(region => {
      regions.push({
        x: parseInt(region.getAttribute("x") || "0"),
        y: parseInt(region.getAttribute("y") || "0"),
        width: parseInt(region.getAttribute("width") || "100"),
        height: parseInt(region.getAttribute("height") || "30"),
        text: region.textContent || "",
      });
    });
    pages.push({ image, textRegions: regions });
  });

  return { title, authors, language: lang, pages };
}

export function generateACBF(metadata: ACBFMetadata): string {
  let xml = '<?xml version="1.0" encoding="UTF-8"?>\n<ACBF xmlns="http://www.fictionbook.org/ACBF-1.0">\n';
  xml += '<metadata>\n';
  xml += `<title>${metadata.title}</title>\n`;
  metadata.authors.forEach(a => xml += `<author>${a}</author>\n`);
  xml += `<language>${metadata.language}</language>\n`;
  xml += '</metadata>\n<body>\n';
  metadata.pages.forEach(page => {
    xml += `<page image="${page.image}">\n`;
    page.textRegions.forEach(r => {
      xml += `<text-region x="${r.x}" y="${r.y}" width="${r.width}" height="${r.height}">${r.text}</text-region>\n`;
    });
    xml += '</page>\n';
  });
  xml += '</body>\n</ACBF>';
  return xml;
}
```

